#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 3b0e3dc4cfaf3293a5ac5566b5d36a2e6b7439441dce0e0cc58b67c132952706.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 3회차: 전극 PNG import. assignment_<side>.json(real.yaml의 condition_assignment와 같은 내용)이 필요하다.
# 끝나면 출력의 review_assets.json, electrode_asset_import_record.json, assets/를 각 data_dir로 복사하고
# real.yaml에 asset_manifest, electrode_import_record({path, sha256})를 넣는다.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # reference (QA4_R00). --max-asset-memory-mb는 기본값이 없는 필수 인자이며 16384는 예시다
    ('import-electrode-assets', [
        '--source-kind', 'hotspot_case_electrode',
        '--root', 'data/input/hotspot/QA4_R00',
        '--numeric-data-dir', 'data/imported/reference',
        '--condition-assignment', 'assignment_reference.json',
        '--cnt-from-dl1-root', 'data/input/dl1',
        '--source-version', 'LAYOUT_V1',
        '--max-asset-memory-mb', '16384',
        '--out', 'data/assets/reference',
    ]),
    # target (QA4_T00). --max-asset-memory-mb는 기본값이 없는 필수 인자이며 16384는 예시다
    ('import-electrode-assets', [
        '--source-kind', 'hotspot_case_electrode',
        '--root', 'data/input/hotspot/QA4_T00',
        '--numeric-data-dir', 'data/imported/target',
        '--condition-assignment', 'assignment_target.json',
        '--cnt-from-dl1-root', 'data/input/dl1',
        '--source-version', 'LAYOUT_V1',
        '--max-asset-memory-mb', '16384',
        '--out', 'data/assets/target',
    ]),
]
LOG_FILE = 'runs/simcompare_3_import_electrode_assets.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
